async function exportPersonalSave(slot) {
  const {blob} = await Sl(slot) ?? {};
  if (!blob?.size || blob.size > 32 * 1024 * 1024) throw new Error("Invalid save");
  const base64 = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result.split(",", 2)[1]);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
  const name = window.CallUpSaveExport?.save(base64);
  if (!name) throw new Error("Could not write backup");
  return name;
}

function PersonalSaveTools({slots, onImport, save}) {
  const [busy, setBusy] = p.useState(false);
  const [status, setStatus] = p.useState("");
  const run = async (slot, exportFile) => {
    setBusy(true);
    setStatus("");
    try {
      if (save && !await save()) throw new Error("Save failed");
      const filename = exportFile ? await exportPersonalSave(slot) : null;
      setStatus(filename ? "Download/CallUp/" + filename : "현재 진행을 저장했어요.");
    } catch {
      setStatus(exportFile ? "세이브를 내보내지 못했어요." : "게임을 저장하지 못했어요.");
    } finally {
      setBusy(false);
    }
  };
  const button = (label, action, key) => e.jsx("button", {
    type: "button", className: "btn", disabled: busy, onClick: action, children: label,
  }, key);
  return e.jsxs("section", {className: "set-g personal-cheats", "aria-label": "세이브", children: [
    e.jsx("div", {className: "set-h", children: "세이브"}),
    e.jsxs("div", {className: "set-card personal-cheats-fields", children: [
      save && button("지금 저장", () => run(Ku(), false)),
      save && button("세이브 내보내기", () => run(Ku(), true)),
      slots?.flatMap((slot, i) => slot
        ? [button((i + 1) + "번 슬롯 내보내기", () => run(i + 1, true), i)]
        : []),
      onImport && e.jsx(PersonalSaveImport, {onImport}),
      e.jsx("p", {role: "status", children: status}),
    ]}),
  ]});
}

function PersonalSaveImport({onImport}) {
  const [status, setStatus] = p.useState("");
  const [loading, setLoading] = p.useState(false);
  const picker = p.useRef(null);
  const load = async event => {
    const file = event.currentTarget.files[0];
    event.currentTarget.value = "";
    if (!file || loading) return;
    setLoading(true);
    setStatus("세이브를 확인하는 중이에요.");
    try {
      if (file.size <= 0 || file.size > 32 * 1024 * 1024) throw new Error("file size");
      let size = 0;
      const capped = file.stream().pipeThrough(new DecompressionStream("gzip"))
        .pipeThrough(new TransformStream({
          transform(chunk, controller) {
            size += chunk.byteLength;
            if (size > 128 * 1024 * 1024) throw new Error("uncompressed size");
            controller.enqueue(chunk);
          },
        }));
      const game = offlineParseSave(await new Response(capped).text());
      if (!game?.agency || typeof game.agency.name !== "string" ||
          !Number.isSafeInteger(game.week) || !game.players || !Array.isArray(game.clubs))
        throw new Error("invalid save");
      const slots = await lc();
      const slot = Ua[slots.findIndex(value => !value)];
      if (!slot) {
        setStatus("빈 슬롯이 필요해요.");
        return;
      }
      const meta = {agency: game.agency.name, week: game.week, savedAt: Date.now()};
      await In("readwrite", store => store.add({blob: file, meta}, `slot${slot}`));
      await onImport();
      setStatus(`${slot}번 슬롯에 가져왔어요.`);
    } catch {
      setStatus("세이브를 가져오지 못했어요. 콜업 야구 세이브만 지원합니다.");
    } finally {
      setLoading(false);
    }
  };
  return e.jsxs("span", {className: "offline-save-import", children: [
    e.jsx("input", {type: "file", ref: picker, hidden: true, onChange: load}),
    e.jsx("button", {type: "button", className: "btn", disabled: loading,
      onClick: () => picker.current.click(), children: "세이브 불러오기"}),
    status && e.jsx("span", {role: "status", children: status}),
  ]});
}
